input.command:
cd /tmp/probe/config && for ext in yaml yml json toml; do d=x_disc_$ext; mkdir -p $d/in; cp x_base/in/*.md $d/in/; case $ext in
 yaml|yml) printf 'name: FROM_%s\n' "$ext" > $d/in/marmite.$ext;;
 json) printf '{"name": "FROM_json"}\n' > $d/in/marmite.json;;
 toml) printf 'name = "FROM_toml"\n' > $d/in/marmite.toml;;
esac; echo "=== $ext ==="; /tmp/orig/marmite_ref $d/in $d/out 2>&1; python3 -c "
import json,sys
print('name=',json.load(open('/tmp/probe/config/$d/out/marmite.json'))['config']['name'])
"; done

cd /tmp/probe/config && for ext in yaml yml json toml txt noext; do d=x_cfg_$ext; mkdir -p $d/in; cp x_base/in/*.md $d/in/; case $ext in
 yaml|yml|txt) f=$d/cfg.$ext; printf 'name: FROM_%s\n' "$ext" > $f;;
 noext) f=$d/cfgfile; printf 'name: FROM_noext\n' > $f;;
 json) f=$d/cfg.json; printf '{"name": "FROM_json"}\n' > $f;;
 toml) f=$d/cfg.toml; printf 'name = "FROM_toml"\n' > $f;;
esac; echo "=== $ext ($f) ==="; /tmp/orig/marmite_ref -c $f $d/in $d/out 2>&1; echo "EXIT=$?"; python3 -c "
import json
print('name=',json.load(open('/tmp/probe/config/$d/out/marmite.json'))['config']['name'])
" 2>&1; done
